package studio.jiayu.neoagent;
import android.content.Context;import org.json.*;import java.io.*;import java.util.*;
final class VisualScopeContracts {
 static void run(Context c){JSONObject out=new JSONObject();int n=0;Vault vault=new Vault(c);String before="";try{before=vault.get(RoutineAccess.KEY);Config conf=new Config();conf.endpoint="https://fixture.invalid/v1";conf.key="LOCAL_TEST_ONLY";conf.vision=true;String pkg=c.getPackageName();vault.put(RoutineAccess.KEY,new JSONObject().put("endpoint",conf.endpoint).put("vision",true).put("apps",new JSONArray().put(pkg)).toString());RoutineAccess access=new RoutineAccess(c);if(access.allows(conf,Collections.singletonList(pkg)))throw new Exception("old masked consent accepted");n++;access.approve(conf,Collections.singletonList(pkg));if(!access.allows(conf,Collections.singletonList(pkg)))throw new Exception("new consent not remembered");n++;if(!"document_write".equals(Action.parse("{\"action\":\"document_write\",\"text\":\"租赁合同\"}").name))throw new Exception("document action unsupported");n++;boolean rejected=false;try{char[] body=new char[8001];Arrays.fill(body,'a');new Action(new JSONObject().put("action","document_write").put("text",new String(body)));}catch(Exception expected){rejected=true;}if(!rejected)throw new Exception("oversized document accepted");n++;for(String text:new String[]{"提交订单","确认并支付","立即支付 ¥35","确认选座"}){if(!ActionGuard.finalAction(text))throw new Exception("final action unguarded");n++;}for(String text:new String[]{"搜索电影","选座购票","查看场次","保存","收货地址"}){if(ActionGuard.finalAction(text))throw new Exception("ordinary navigation blocked");n++;}try{Class.forName("studio.jiayu.neoagent.LocalOcr");throw new Exception("OCR still bundled");}catch(ClassNotFoundException expected){n++;}android.view.accessibility.AccessibilityNodeInfo button=android.view.accessibility.AccessibilityNodeInfo.obtain();button.setViewIdResourceName("native-new-blank-btn");if(!NativeLabels.resourceAction(button))throw new Exception("hybrid button resource lost");n++;button.setViewIdResourceName("app");if(NativeLabels.resourceAction(button))throw new Exception("root promoted to action");n++;ControlService fake=new ControlService();try{DocumentRuntime doc=fake.document;fake.task="修改租赁合同";doc.created=true;doc.bodyVerified=true;doc.name="测试租赁合同_fixture";doc.saveAt=System.currentTimeMillis();if(!doc.next(false,"").contains("back"))throw new Exception("save receipt did not lead to list readback");n++;if(doc.exposedControl("他人文档.docx"))throw new Exception("unowned file promoted to control");n++;if(!doc.exposedControl("测试租赁合同_fixture.docx")||!doc.exposedControl("writer frame"))throw new Exception("owned file or editor reference lost");n++;doc.saved=true;doc.reopened=true;doc.editVerified=true;if(doc.completed())throw new Exception("unpersisted edit accepted");n++;doc.persistedEdit=true;doc.reopen.wrote(2);doc.reopen.listObserved();doc.reopen.openRequested();doc.reopen.bodyRead();if(!doc.completed())throw new Exception("verified edited file rejected");n++;if(!Action.parse("{\"action\":\"document_focus\"}").name.equals("document_focus"))throw new Exception("native focus unavailable");n++;}finally{fake.runtimeHealth.close();fake.worker.shutdownNow();fake.workerScreenshot.shutdownNow();}if(!DocumentScope.sameFile("测试租赁合同_fixture.docx，今天 19:00","测试租赁合同_fixture"))throw new Exception("file metadata label lost");n++;if(DocumentScope.sameFile("测试租赁合同_fixture_备份.docx","测试租赁合同_fixture"))throw new Exception("different file accepted");n++;out.put("success",true).put("passed",n).put("network_calls",0).put("gestures",0);}catch(Exception e){try{out.put("success",false).put("passed",n).put("failure",e.getMessage());}catch(Exception ignored){}}finally{try{if(before.isEmpty())vault.remove(RoutineAccess.KEY);else vault.put(RoutineAccess.KEY,before);try(FileOutputStream f=c.openFileOutput("visual-scope-contracts.json",0)){f.write(out.toString(2).getBytes("UTF-8"));}}catch(Exception ignored){}}}
}
